window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-19e3f9fa357ccb7b"]={"versions": [{"id": "FIG-19e3f9fa357ccb7b", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Prozessdiagramm (Software &amp; Systems Process Engineering Metamodel) für die Methodik und Aktivitäten der AUTOSAR-Timing-Analyse im Kontext der Einführung serviceorientierter Kommunikation (Service-Oriented Communication, SOC). Das Diagramm modelliert den methodischen Daten- und Kontrollfluss zwischen Prozessaktivitäten (Tasks) und Arbeitsergebnissen (Work Products) zur schrittweisen Erstellung und modellbasierten Analyse von Timing-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende SPEM-Entitäten und Beziehungen:</p>\n<p class=\"fig-p\"><strong>Tasks (Aktivitäten, dargestellt als gelbe Pfeilsymbole/Step-Shapes):</strong></p>\n<ul class=\"fig-list\"><li><code>Create Timing Model (with Service Discovery)</code>: Erweitert das bestehende Modell um Service-Discovery-Aspekte.\n</li><li><code>Create Timing Model (with Detailed Service Oriented Communication)</code>: Detailliert das Modell hinsichtlich serviceorientierter Kommunikation.\n</li><li><code>Perform Model-Based Timing Analysis (of Service Discovery)</code>: Führt die Timing-Analyse für Service Discovery durch.\n</li><li><code>Perform Model-Based Timing Analysis (of Detailed S.O.C.)</code>: Führt die Timing-Analyse für die detaillierte serviceorientierte Kommunikation durch.\n</li></ul>\n<p class=\"fig-p\"><strong>Work Products (Artefakte, dargestellt als Dokumentensymbole):</strong></p>\n<ul class=\"fig-list\"><li><code>existing Timing Model</code>: Ausgangs-Timing-Modell.\n</li><li><code>Timing Model (with Service Discovery)</code>: Zwischenartefakt nach Modellierung der Service Discovery.\n</li><li><code>Timing Model (with Detailed Service Oriented Communication)</code>: Zwischenartefakt nach detaillierter SOC-Modellierung.\n</li><li><code>Timing Analysis Report (Model Based)</code>: Analysebericht als Zielartefakt.\n</li></ul>\n<p class=\"fig-p\"><strong>Kanten/Beziehungen:</strong></p>\n<ul class=\"fig-list\"><li>Unbeschriftete gerichtete Pfeile verbinden Artefakte als Eingaben zu Tasks bzw. Tasks als Erzeuger zu Artefakten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozess verläuft in zwei aufeinander aufbauenden Modellierungs- und Analysepfaden:</p>\n<ol class=\"fig-list\"><li>Ausgehend von <code>existing Timing Model</code> wird durch den Task <code>Create Timing Model (with Service Discovery)</code> das Artefakt <code>Timing Model (with Service Discovery)</code> erzeugt.\n</li><li>Dieses Zwischenmodell speist zwei parallele bzw. sequentielle Pfade:\n<ul class=\"fig-list\"><li>Es dient als Eingabe für <code>Perform Model-Based Timing Analysis (of Service Discovery)</code>, dessen Ergebnisse in <code>Timing Analysis Report (Model Based)</code> einfließen.\n</li><li>Es dient als Basis für den Folgetask <code>Create Timing Model (with Detailed Service Oriented Communication)</code>, der das Artefakt <code>Timing Model (with Detailed Service Oriented Communication)</code> erstellt.\n</li></ul>\n</li><li>Das detaillierte Modell wird im Task <code>Perform Model-Based Timing Analysis (of Detailed S.O.C.)</code> analysiert und liefert ebenfalls Ergebnisse an das gemeinsame Artefakt <code>Timing Analysis Report (Model Based)</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Prozessmodell definiert eine methodische Leitlinie zur Durchführung von Timing-Analysen bei dynamischer serviceorientierter Kommunikation. Bei der Implementierung der AUTOSAR-Methodik ist sicherzustellen, dass Timing-Modellierungswerkzeuge die inkrementelle Anreicherung um Service Discovery sowie detaillierte SOC-Eigenschaften unterstützen. Die Analyseergebnisse beider Teilaspekte müssen in einem zusammenfassenden modellbasierten Analysebericht konsolidiert werden können.</p>"}, {"id": "FIG-1a7a5cc48fe396c6", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-Prozessdiagramm (Software &amp; Systems Process Engineering Metamodel) für die Methodik und Aktivitäten der AUTOSAR-Timing-Analyse im Kontext der Einführung serviceorientierter Kommunikation (Service-Oriented Communication, SOC). Das Diagramm modelliert den methodischen Daten- und Kontrollfluss zwischen Prozessaktivitäten (Tasks) und Arbeitsergebnissen (Work Products) zur schrittweisen Erstellung und modellbasierten Analyse von Timing-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende SPEM-Entitäten und Beziehungen:</p>\n<p class=\"fig-p\"><strong>Tasks (Aktivitäten, dargestellt als gelbe Pfeilsymbole):</strong></p>\n<ul class=\"fig-list\"><li><code>Create Timing Model (with Service Discovery)</code>\n</li><li><code>Create Timing Model (with Detailed Service Oriented Communication)</code>\n</li><li><code>Perform Model-Based Timing Analysis (of Service Discovery)</code>\n</li><li><code>Perform Model-Based Timing Analysis (of Detailed S.O.C.)</code>\n</li><li><code>Verify Timing</code>: Führt den formalen Verifikationsschritt zwischen Analyseergebnissen und Anforderungen aus.\n</li></ul>\n<p class=\"fig-p\"><strong>Work Products (Artefakte, dargestellt als Dokumentensymbole):</strong></p>\n<ul class=\"fig-list\"><li><code>Timing Model (existing)</code>: Ausgangs-Timing-Modell.\n</li><li><code>Timing Model (with Service Discovery)</code>: Zwischenartefakt für Service Discovery.\n</li><li><code>Timing Model (with Detailed Service Oriented Communication)</code>: Detailliertes SOC-Timing-Modell.\n</li><li><code>Timing Requirements</code>: Spezifikation der geltenden Timing-Vorgaben und -Schranken.\n</li><li><code>Timing Analysis Report (Model Based)</code>: Konsolidierter modellbasierter Analysebericht.\n</li><li><code>Timing Verification Report</code>: Endgültiger Verifikationsbericht über die Erfüllung der Timing-Anforderungen.\n</li></ul>\n<p class=\"fig-p\"><strong>Kanten/Beziehungen:</strong></p>\n<ul class=\"fig-list\"><li>Gerichtete Verbindungspfeile sind explizit mit SPEM-Stereotypen und Kardinalitäten annotiert:\n<ul class=\"fig-list\"><li><code>1 «input»</code>: Eingehende Artefakte an Tasks (jeweils Kardinalität 1).\n</li><li><code>«output» 1</code>: Ausgehende Artefakte von Tasks (jeweils Kardinalität 1).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gliedert sich in Modellierung, Analyse und Verifikation:</p>\n<ol class=\"fig-list\"><li><code>Timing Model (existing)</code> wird als <code>1 «input»</code> an <code>Create Timing Model (with Service Discovery)</code> übergeben; dieser Task erzeugt als <code>«output» 1</code> das Artefakt <code>Timing Model (with Service Discovery)</code>.\n</li><li><code>Timing Model (with Service Discovery)</code> wird zweifach verwendet:\n<ul class=\"fig-list\"><li>Als <code>1 «input»</code> für <code>Perform Model-Based Timing Analysis (of Service Discovery)</code>.\n</li><li>Als <code>1 «input»</code> für <code>Create Timing Model (with Detailed Service Oriented Communication)</code>, welcher als <code>«output» 1</code> das Artefakt <code>Timing Model (with Detailed Service Oriented Communication)</code> erzeugt.\n</li></ul>\n</li><li><code>Timing Model (with Detailed Service Oriented Communication)</code> geht als <code>1 «input»</code> in den Task <code>Perform Model-Based Timing Analysis (of Detailed S.O.C.)</code>.\n</li><li>Beide Analysetasks liefern ihren Ausgang (<code>«output» 1</code>) in das gemeinsame Artefakt <code>Timing Analysis Report (Model Based)</code> (jeweils mit Eingangs-Kardinalität <code>1</code>).\n</li><li><code>Timing Analysis Report (Model Based)</code> (<code>1 «input»</code>) und <code>Timing Requirements</code> (<code>1 «input»</code>) werden im Task <code>Verify Timing</code> zusammengeführt.\n</li><li><code>Verify Timing</code> liefert als <code>«output» 1</code> den abschließenden <code>Timing Verification Report</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die formale Prozessmodellierung bindet die Timing-Verifikation als obligatorischen Abschlussschritt ein: Eine Timing-Analyse ist erst mit dem Abgleich der ermittelten Metriken (<code>Timing Analysis Report (Model Based)</code>) gegen die spezifizierten Anforderungen (<code>Timing Requirements</code>) im Task <code>Verify Timing</code> abgeschlossen. Toolketten und Entwicklungsprozesse müssen die Rückverfolgbarkeit bis zum <code>Timing Verification Report</code> sowie die exakten 1:1-Artefaktbeziehungen und Stereotypen (<code>«input»</code>, <code>«output»</code>) einhalten.</p>"}], "trans": [{"from": "FIG-19e3f9fa357ccb7b", "to": "FIG-1a7a5cc48fe396c6", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Erweiterung des Prozessablaufs um den Task <code>Verify Timing</code>, der die Work Products <code>Timing Analysis Report (Model Based)</code> und <code>Timing Requirements</code> zusammenführt.\n</li><li>Hinzufügen der Work Products <code>Timing Requirements</code> (Eingang für <code>Verify Timing</code>) und <code>Timing Verification Report</code> (Ausgang von <code>Verify Timing</code>).\n</li><li>Einführung formaler SPEM-Rollen-Stereotypen (<code>«input»</code>, <code>«output»</code>) sowie expliziter Kardinalitäten (<code>1</code>) an sämtlichen Kanten zwischen Tasks und Work Products.\n</li><li>Anpassung der Beschriftung von <code>existing Timing Model</code> zu <code>Timing Model (existing)</code>.\n</li></ul>"}]};
